{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Cilomilast, a lipophilic neutral compound with low aqueous solubility, had a mean absolute oral bioavailability of 96% (92–102%) in healthy humans, directly demonstrating that high lipophilicity and neutral character do not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Tramadol, a basic tertiary-amine drug, showed absolute oral bioavailability of 68.4% in humans, supporting high F for the query's amine-containing lipophilic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Deramciclane, a lipophilic tertiary-amine drug, had absolute oral bioavailability of 44.3% in healthy volunteers, providing a lower-bound but still high (>20%) human F measurement that transfers to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Thalidomide, a moderately lipophilic neutral drug with slow absorption, showed high oral bioavailability (80–100%) in humans, supporting that neutral, poorly soluble compounds can still exceed 20% F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Methylene blue had absolute oral bioavailability of 72.3% in humans, adding independent evidence that diverse structures with high assay-transfer scores yield high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All provided experimental analogues, with high assay-transfer scores (0.948–0.981), report human oral bioavailability values well above 20%, ranging from ~36% to ~100%. No contradictory low-bioavailability evidence was provided. The physicochemical prior is mixed, but the strong, transferable human absolute-bioavailability data support a high F prediction for the query.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the provided evidence set.",
    "All supporting analogues are structurally distinct from the query; transfer relies on high assay-transfer scores rather than direct query data.",
    "First-pass metabolism and solubility-limited absorption for the query are not directly quantified in the evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

